import{z as d,x as p,o as t,c,q as r,j as n,D as e,d as l,s as E,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"CSE 与 GVN","description":"","frontmatter":{"title":"CSE 与 GVN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cse-gvn.md","filePath":"cs/cse-gvn.md","lastUpdated":1791413859000}'),A={name:"cs/cse-gvn.md"};function C(B,a,m,u,h,b){const s=p("Mermaid");return t(),c("div",null,[a[2]||(a[2]=r('<h1 id="cse-与-gvn" tabindex="-1">CSE 与 GVN <a class="header-anchor" href="#cse-与-gvn" aria-label="Permalink to &quot;CSE 与 GVN&quot;">​</a></h1><div class="epigraph"><p>公共子表达式：同一运算算两次则复用。全局值编号给每个值一个类，按哈希把等价计算并成一个领导。</p><footer>—— 据 Cocke, Global Common Subexpression Elimination；Alpern, Wegman and Zadeck, Detecting Equality of Variables in Programs, 1988；Click, Global Value Numbering 整理</footer></div><p>上一课<a href="/cs/sccp">SCCP</a>处理常量这一格。缺口是<strong>结构相等</strong>：<code>a+b</code> 在两处出现，或经代数 <code>a+b</code> 与 <code>b+a</code>（若交换）。CSE 是数据流「可用表达式」的消除；GVN 用编号。主干<a href="/cs/available-expr">可用表达式</a>已给方程。本课钉 SSA 上的实践，不重推位向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可用表达式：程序点上「若再算 \\(a+b\\) 则与先前同一」。局部 CSE 在基本块哈希表即可。全局：须支配——复用点被计算点支配，否则要插入或放弃。GVN：值编号，φ 与运算的合同。缺口是<strong>何时可删第二次运算</strong>，不是常量格。</p><p>Click 的 GVN 可与 SCCP 类似地乐观。代数化简（<code>x-x</code>）属同一遍或相邻遍。</p><p><span class="marginnote">「支配」是图论术语：若从函数入口走到块 B 的每条路都必须经过块 A，就说 A 支配 B。直觉上，只有计算点&quot;把守着通往复用点的所有路&quot;，复用才安全——否则存在一条绕开计算点的路径，会用到从未算过的值。</span></p><h3 id="编号不是「名字字符串」" tabindex="-1">编号不是「名字字符串」 <a class="header-anchor" href="#编号不是「名字字符串」" aria-label="Permalink to &quot;编号不是「名字字符串」&quot;">​</a></h3><p><code>add x1, y1</code> 与 <code>add x2, y2</code> 仅当 \\(x\\)、\\(y\\) 编号相同才同号。SSA 使「同名」等价于「同值」对标量成立；内存不算，除非别名说只读。</p><p><span class="marginnote">Cocke 早期 CSE。AWZ 1988。Click 的 GVN。龙书 6.1.2 / 9.1。Appel 有局部值编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部：块内表，键为操作码+操作数编号。全局：RPO 遍历支配树，或 AWZ 的哈希。消除：第二次改成对领导的拷贝，再拷贝传播。</p>',12)),(t(),n(i,null,{default:e(()=>[E(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E8%BF%90%E7%AE%97%22%5D%20--%3E%20VN%5B%22%E5%80%BC%E7%BC%96%E5%8F%B7%22%5D%0A%20%20VN%20--%3E%20CSE%5B%22%E5%A4%8D%E7%94%A8%E9%A2%86%E5%AF%BC%22%5D%0A%20%20CSE%20--%3E%20COPY%5B%22%E6%8B%B7%E8%B4%9D%E4%BC%A0%E6%92%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"与 LICM：循环里不变的公共表达式先外提再编号，后课。不要对可能陷阱的运算（除零、load）在不可靠路径上复用——控制依赖。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[l("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"交换律：规范化操作数序（编号较小者在前）再哈希。浮点：交换律在 IEEE 下对 NaN 载荷有坑（带符号的零不碍交换，碍的是 \\(-0+0\\) 不等于 \\(-0\\) 这类恒等替换），fast-math 才开。",-1)),(t(),n(i,null,{default:e(()=>[E(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22a%20%2B%20b%22%5D%20--%3E%20N%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%E6%93%8D%E4%BD%9C%E6%95%B0%E5%BA%8F%22%5D%0A%20%20B%5B%22b%20%2B%20a%22%5D%20--%3E%20N%0A%20%20N%20--%3E%20H%5B%22%E6%9F%A5%E7%BC%96%E5%8F%B7%E5%93%88%E5%B8%8C%E8%A1%A8%22%5D%0A%20%20H%20--%3E%7C%22%E5%B7%B2%E5%90%8C%E5%8F%B7%22%7C%20L%5B%22%E5%A4%8D%E7%94%A8%E9%A2%86%E5%AF%BC%EF%BC%8C%E5%88%A0%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%BF%90%E7%AE%97%22%5D%0A%20%20H%20--%3E%7C%22%E6%9C%AA%E7%99%BB%E8%AE%B0%22%7C%20I%5B%22%E7%99%BB%E8%AE%B0%E4%B8%BA%E6%96%B0%E9%A2%86%E5%AF%BC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">交换律规范化可以想象成整理手套：把两只手套一律排成&quot;左手在前&quot;再放进同一格抽屉，之后无论你按什么顺序掏，都认得出是同一副。编译器把 \\(a+b\\) 与 \\(b+a\\) 都重排成小编号在前，哈希表才认得出它们等价。</span></p><p><span class="marginnote">初学者容易以为&quot;加法交换律天经地义，编译器随时可以换序&quot;。实际上 IEEE 754 浮点里 NaN 的载荷归属未定，\\(a+b\\) 与 \\(b+a\\) 在极端情形可能不等价（带符号的零不碍交换，碍的是 \\(-0+0\\) 不等于 \\(-0\\) 这类恒等），编译器默认不敢动，只有你显式声明 fast-math 这类许可后才肯重排。</span></p><p>PRE（部分冗余）后课：表达式在部分路径可用时插入使全局可用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写别名。后课默认：标量纯运算可 GVN。下一课 DCE/ADCE：编号后的死拷贝与死块。</p><p>也不把 CSE 当加密哈希碰撞问题；编号哈希冲突只影响编译期表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSE：复用已算的表达式；GVN 用值编号找等价。</li><li>支配决定全局复用点。</li><li>内存与浮点要额外纪律。</li><li>出处：Cocke；Alpern–Wegman–Zadeck, 1988；Click；龙书。</li></ul>',8))])}const N=d(A,[["render",C]]);export{S as __pageData,N as default};
